/* (OberVave 3) the rate-dependent tables at fs – the formulas of tools/gen_tables.py. Computed once at the start in
 * double precision with small exact helpers (the firmware has no libm; the SDK's fast vd_* lose the tiny
 * coefficients of long envelopes) */
static double t_exp(double x)                     /* e^x: x = k ln2 + r, |r| <= ln2/2, Taylor */
{
    int k = (int)(x / 0.6931471805599453 + (x < 0 ? -0.5 : 0.5)), n;
    double r = x - k * 0.6931471805599453, term = 1.0, sum = 1.0;
    for (n = 1; n < 18; n++) { term *= r / n; sum += term; }
    for (; k > 0; k--) sum *= 2.0;
    for (; k < 0; k++) sum *= 0.5;
    return sum;
}
static double t_1mexp(double x)                   /* 1 - e^-x, exact for small x too */
{
    double term = x, sum = 0.0; int n;
    if (x > 0.5) return 1.0 - t_exp(-x);
    for (n = 1; n < 20; n++) { sum += term; term *= -x / (n + 1); }
    return sum;
}
static double t_tan(double x)                     /* 0 <= x < pi/2: sin / cos, Taylor */
{
    double s = 0, c = 0, ts = x, tc = 1.0; int n;
    for (n = 0; n < 16; n++) { s += ts; c += tc; ts *= -x * x / ((2 * n + 2) * (2 * n + 3)); tc *= -x * x / ((2 * n + 1) * (2 * n + 2)); }
    return s / c;
}
#define T_LN2 0.6931471805599453
static uint32_t k_block(double tau_s, double fs)  /* one-pole coefficient per control block, Q24 */
{
    double k = 16777216.0 * t_1mexp((double)CTL / (tau_s * fs));
    return k < 1.0 ? 1u : k > 16777215.0 ? 16777215u : (uint32_t)(k + 0.5);
}
static void obv_tables_init(float fs_f)
{
    double fs = fs_f;
    int i;
    for (i = 0; i < 12; i++) INC_C9[i] = (uint32_t)(440.0 * t_exp(T_LN2 * (120 + i - 69) / 12.0) / fs * 4294967296.0);
    for (i = 0; i < 137; i++) {
        double f = 440.0 * t_exp(T_LN2 * (i - 69) / 12.0);
        if (f > 0.45 * fs) f = 0.45 * fs;
        SVF_G[i] = (uint16_t)(4096.0 * t_tan(3.141592653589793 * f / fs) + 0.5);
    }
    for (i = 0; i < 128; i++) {
        double v = i / 127.0, ms = 0.5 * t_exp(v * 9.903487552536127), gms = 5.0 * t_exp(v * 6.907755278982137);
        double hz = 0.05 * t_exp(v * 6.396929655216146), g;   /* (ln 20000, ln 1000, ln 600) */
        ENV_K_ATT[i] = k_block(ms / 1000.0 / 1.466, fs);
        ENV_K_DEC[i] = k_block(ms / 1000.0 / 3.0, fs);
        g = 65536.0 * t_1mexp((double)CTL / (gms / 3000.0 * fs));
        GLIDE_K[i] = (uint16_t)(g < 1.0 ? 1.0 : g > 65535.0 ? 65535.0 : g + 0.5);
        LFO_INC[i] = (uint32_t)(hz * CTL / fs * 4294967296.0);
        LFO_DELAY_BLK[i] = (uint16_t)(5000.0 * v * v / 1000.0 * fs / CTL + 0.5);
    }
}
